@csrf_exempt
@require_http_methods(["GET"])
@json_api
def employees_list(request):
    user = request.api_user
    qs = visible_employees_for(user)[:200]
    return JsonResponse(
        {
            "employees": [
                {
                    "id": e.id,
                    "employee_number": e.employee_number,
                    "name": e.user.display_name,
                    "department": e.department.code if e.department else None,
                    "manager_id": e.manager_id,
                    "job_title": e.job_title,
                    "employment_status": e.employment_status,
                }
                for e in qs
            ]
        }
    )

@csrf_exempt
@require_http_methods(["GET"])
@json_api
def employee_detail(request, employee_id: int):
    user = request.api_user
    e = visible_employees_for(user).filter(pk=employee_id).first()
    if e is None:
        return JsonResponse({"detail": "Not found."}, status=404)
    data = {
        "id": e.id,
        "employee_number": e.employee_number,
        "name": e.user.display_name,
        "email": e.user.email,
        "department": e.department.code if e.department else None,
        "manager_id": e.manager_id,
        "job_title": e.job_title,
        "employment_status": e.employment_status,
        "employment_type": e.employment_type,
        "start_date": e.start_date.isoformat() if e.start_date else None,
    }
    if user.is_superuser or user.role == "hr_admin":
        data["internal_notes"] = e.internal_notes
    return JsonResponse(data)

@csrf_exempt
@require_http_methods(["GET"])
@json_api
def my_compensation(request):
    user = request.api_user
    e = visible_employees_for(user).filter(user_id=user.id).first()
    if e is None:
        return JsonResponse({"records": []})
    latest = CompensationRecord.objects.filter(employee=e).order_by("-effective_date").first()
    if not latest:
        return JsonResponse({"records": []})
    return JsonResponse(
        {
            "records": [
                {
                    "base_salary": str(latest.base_salary),
                    "bonus_target": str(latest.bonus_target),
                    "currency": latest.currency,
                    "effective_date": (
                        latest.effective_date.isoformat() if latest.effective_date else None
                    ),
                }
            ]
        }
    )

