@csrf_exempt
@require_http_methods(["GET"])
@json_api
def policies_list(request):
    user = request.api_user
    from policies.views import _audience_for_user

    qs = Policy.objects.filter(is_archived=False)
    if user.role != "hr_admin" and not user.is_superuser:
        qs = qs.filter(audience__in=list(_audience_for_user(user)))
    return JsonResponse(
        {
            "policies": [
                {
                    "id": p.id,
                    "code": p.code,
                    "title": p.title,
                    "version": p.version,
                    "audience": p.audience,
                }
                for p in qs.order_by("title")
            ]
        }
    )

@csrf_exempt
@require_http_methods(["POST"])
def receive_test_webhook(request):
    """Local-only stub: developers can POST here to verify the API surface."""
    user = _auth_user_for_json(request)
    if user is None:
        return JsonResponse({"detail": "Authentication required."}, status=401)
    try:
        body = json.loads(request.body or b"{}")
    except json.JSONDecodeError:
        return JsonResponse({"detail": "Invalid JSON."}, status=400)
    return JsonResponse({"echoed": body, "by": user.username})

